     1→/**
     2→ * P1-6 QueryChat 拆分：SSE 流解析通用工具（P2-7 问数流式链路）。
     3→ * 按 event/data 分段解析服务端 text/event-stream 响应；错误事件直接抛异常由调用方统一降级。
     4→ */
     5→
     6→/** SSE 阶段事件 → 用户可读的进度文案 */
     7→export function stageLabel(stage: string): string {
     8→  switch (stage) {
     9→    case 'understanding':
    10→      return '正在理解问题语义并匹配数据字段…';
    11→    case 'introspecting':
    12→      return '数据自省中：正在确认真实取值…';
    13→    case 'sql_ready':
    14→      return 'SQL 已生成，正在安全校验并执行…';
    15→    case 'executed':
    16→      return 'SQL 已执行，正在生成分析解读…';
    17→    case 'analyzing':
    18→      return '正在基于真实数据生成洞察…';
    19→    default:
    20→      return '处理中…';
    21→  }
    22→}
    23→
    24→export interface SseStreamHandlers {
    25→  /** 阶段进度事件（stage 文案直接可渲染；info 携带事件附加字段，如 sql_ready/executed 的 sql） */
    26→  onStage?: (label: string, stage: string, info?: Record<string, any>) => void;
    27→  /** M1 推导留痕步骤事件（追加步骤器） */
    28→  onTrace?: (step: any) => void;
    29→  /** 终端事件（done / clarify / refuse），payload 与非流式 JSON 响应同构 */
    30→  onTerminal?: (event: 'done' | 'clarify' | 'refuse', data: any) => void;
    31→}
    32→
    33→/** 消费 SSE 响应体：逐块解码、按空行分段、event:/data: 行解析后分发回调 */
    34→export async function readSseStream(response: Response, handlers: SseStreamHandlers): Promise<void> {
    35→  const reader = response.body!.getReader();
    36→  const decoder = new TextDecoder();
    37→  let buffer = '';
    38→  while (true) {
    39→    const { done, value } = await reader.read();
    40→    if (done) break;
    41→    buffer += decoder.decode(value, { stream: true });
    42→    const parts = buffer.split('\n\n');
    43→    buffer = parts.pop() || '';
    44→    for (const part of parts) {
    45→      let eventName = 'message';
    46→      let dataStr = '';
    47→      for (const line of part.split('\n')) {
    48→        if (line.startsWith('event:')) eventName = line.slice(6).trim();
    49→        else if (line.startsWith('data:')) dataStr += line.slice(5).trim();
    50→      }
    51→      if (!dataStr) continue;
    52→      let data: any;
    53→      try {
    54→        data = JSON.parse(dataStr);
    55→      } catch {
    56→        continue;
    57→      }
    58→      if (eventName === 'stage') {
    59→        const stage = String(data?.stage || '');
    60→        const { stage: _stage, ...info } = data || {};
    61→        handlers.onStage?.(stageLabel(stage), stage, info);
    62→      } else if (eventName === 'trace') {
    63→        if (data && typeof data.title === 'string') handlers.onTrace?.(data);
    64→      } else if (eventName === 'done' || eventName === 'clarify' || eventName === 'refuse') {
    65→        handlers.onTerminal?.(eventName, data);
    66→      } else if (eventName === 'error') {
    67→        throw new Error(String(data?.error || '查询失败'));
    68→      }
    69→    }
    70→  }
    71→}
    72→

